const data = $json.body ?? $json;
if (typeof data.request_id !== 'string' || !/^[A-Za-z0-9_-]{16,128}$/.test(data.request_id)) throw new Error('Falta request_id estable y válido');
if (!data.master || typeof data.master !== 'object' || Array.isArray(data.master)) throw new Error('Falta MASTER como objeto JSON');
const destination = String(data.CREAR_EN ?? '').toUpperCase();
if (!['OPURO','OPOL','AMBOS'].includes(destination)) throw new Error('CREAR_EN inválido');
if (data.PUBLICAR !== false) throw new Error('Esta prueba sólo admite PUBLICAR=false');
const binary = {};
for (const [key, required] of [['hero_file', destination !== 'OPOL'], ['featured_file', true]]) {
  const file = data[key];
  if (!file && !required) continue;
  if (!file || typeof file.base64 !== 'string' || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(file.base64) || !file.base64.length || file.base64.length > 14000000) throw new Error('Imagen inválida o ausente: '+key);
  const buf = Buffer.from(file.base64, 'base64');
  let mime, ext;
  if (buf.length >= 8 && buf.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))) { mime='image/png'; ext='png'; }
  else if (buf.length >= 3 && buf[0]===255 && buf[1]===216 && buf[2]===255) { mime='image/jpeg'; ext='jpg'; }
  else if (buf.length >= 12 && buf.subarray(0,4).toString()==='RIFF' && buf.subarray(8,12).toString()==='WEBP') { mime='image/webp'; ext='webp'; }
  else throw new Error('Formato no admitido: '+key);
  binary[key] = await this.helpers.prepareBinaryData(buf, key+'.'+ext, mime);
}
return {json:{json: JSON.stringify(data.master), CREAR_EN:destination, PUBLICAR:false, request_id:data.request_id}, binary};

let envelope = $json.body ?? $json;

const destinoRaw = String(envelope.CREAR_EN ?? '').trim().toUpperCase();
const destinosValidos = ['OPURO','OPOL','AMBOS'];
if (!destinosValidos.includes(destinoRaw)) {
  throw new Error(`CREAR_EN inválido o ausente. Valor recibido: "${destinoRaw}". Usa OPURO, OPOL o AMBOS.`);
}
const publicarRaw = envelope.PUBLICAR;
const publish = Array.isArray(publicarRaw)
  ? publicarRaw.length > 0
  : (publicarRaw === true || ['sí','si','true','1','on'].includes(String(publicarRaw ?? '').trim().toLowerCase()));
const execution = {
  destination: destinoRaw,
  create_opuro: destinoRaw === 'OPURO' || destinoRaw === 'AMBOS',
  create_opol: destinoRaw === 'OPOL' || destinoRaw === 'AMBOS',
  publish
};

// v1.1.7: el MASTER llega pegado en "json" O como archivo "json_file".
const pastedJson = typeof envelope.json === 'string' ? envelope.json.trim() : '';
const binary = $input.item.binary ?? {};
const binaryKeys = Object.keys(binary);
const fileKey = binary.json_file ? 'json_file' : null;
const hasFile = Boolean(fileKey);

if (pastedJson && hasFile) {
  throw new Error('Entrega el OPMX MASTER de una sola forma: pega el JSON en el cuadro de texto O sube el archivo .json, no ambos.');
}
if (!pastedJson && !hasFile) {
  throw new Error('Falta el OPMX MASTER. Pega el JSON completo en el cuadro de texto o sube un archivo .json.');
}

let d;
if (hasFile) {
  const meta = binary[fileKey] ?? {};
  const fileName = String(meta.fileName ?? '').trim();
  const extension = String(meta.fileExtension ?? '').trim().toLowerCase();
  if (fileName && !/\.json$/i.test(fileName) && extension !== 'json') {
    throw new Error(`El archivo subido debe ser .json. Archivo recibido: ${fileName || '(sin nombre)'}`);
  }

  let fileText;
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, fileKey);
    fileText = buffer.toString('utf8').replace(/^\uFEFF/, '').trim();
  } catch (error) {
    throw new Error(`No fue posible leer el archivo JSON subido: ${error.message}`);
  }
  if (!fileText) throw new Error('El archivo JSON subido está vacío.');

  try { d = JSON.parse(fileText); }
  catch (error) { throw new Error(`El archivo subido no contiene JSON válido: ${error.message}`); }
} else {
  try { d = JSON.parse(pastedJson); }
  catch (error) { throw new Error(`El campo "json" no contiene JSON válido: ${error.message}`); }
}

if (typeof d === 'string') {
  try { d = JSON.parse(d.trim()); }
  catch (error) { throw new Error(`El OPMX MASTER recibido no contiene JSON válido: ${error.message}`); }
}

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}
function arr(v) {
  if (Array.isArray(v)) return v.map(x => str(x)).filter(Boolean);
  if (typeof v === 'string' && v.trim()) return v.split(',').map(x => x.trim()).filter(Boolean);
  return [];
}
function imageSlugFromUrl(url, label) {
  if (!url) return '';
  try {
    const cleanUrl = String(url).split('?')[0].split('#')[0];
    const filename = decodeURIComponent(cleanUrl.substring(cleanUrl.lastIndexOf('/') + 1));
    return filename.replace(/\.[a-zA-Z0-9]+$/, '').trim();
  } catch (error) {
    throw new Error(`No fue posible obtener el nombre de archivo desde ${label}: ${url}`);
  }
}

const SEO = d.SEO ?? d.seo ?? {};
const PUB = d.PUBLICACION ?? d.publication ?? {};
// Contrato v1.2: AUTOR_ID está prohibido en el MASTER.
// La identidad técnica del autor pertenece al Publisher.
const forbiddenAuthorFields = [
  ['PUBLICACION.AUTOR_ID', PUB.AUTOR_ID],
  ['PUBLICACION.author_id', PUB.author_id],
  ['AUTOR_ID', d.AUTOR_ID],
  ['author_id', d.author_id]
].filter(([, value]) => value !== undefined && value !== null);

if (forbiddenAuthorFields.length) {
  throw new Error(
    'CONTRATO_V1_2_AUTOR_ID_PROHIBIDO: el MASTER no debe contener AUTOR_ID. Campos detectados: ' +
    forbiddenAuthorFields.map(([name]) => name).join(', ') + '.'
  );
}

const authorId = 3;
const authorSource = 'PUBLISHER_OPURO_REDACCION_OPMX';

const IMAGES = d.IMAGENES ?? d.images ?? {};

const HERO = IMAGES.HERO_OPURO ?? IMAGES.hero_opuro ?? {};
const FEATURED_OPURO = IMAGES.DESTACADA_OPURO ?? IMAGES.featured_opuro ?? {};
const FEATURED_OPOL = IMAGES.DESTACADA_OPOL ?? IMAGES.featured_opol ?? {};

const title = str(SEO.TITULO_SEO ?? d.TEXTO_EDITORIAL?.TITULO ?? d.article?.title);
const subtitle = str(SEO.SUBTITULO ?? d.TEXTO_EDITORIAL?.SUBTITULO ?? d.article?.subtitle);
const slug = str(SEO.SLUG ?? SEO.slug);
const excerpt = str(PUB.EXTRACTO ?? PUB.excerpt ?? SEO.EXTRACTO ?? SEO.excerpt ?? d.TEXTO_EDITORIAL?.ENTRADILLA);
const metaDescription = str(SEO.METADESCRIPCION ?? SEO.meta_description ?? excerpt);
const primaryKeyword = str(SEO.KEYWORD_PRINCIPAL ?? SEO.primary_keyword);
const secondaryKeywords = arr(SEO.KEYWORDS_SECUNDARIAS ?? SEO.secondary_keywords);
const keywordsAll = str(SEO.KEYWORDS_TODAS ?? SEO.keywords_todas ?? SEO.all_keywords_string);
const keywordsList = arr(SEO.KEYWORDS_TODAS_LISTA ?? SEO.keywords_todas_lista ?? SEO.KEYWORDS_TODAS ?? SEO.all_keywords);
const CATS=d.CATEGORIAS??d.categorias??{};
const OPUROCAT=CATS.OPURO??CATS.opuro??{};
const OPOLCAT=CATS.OPOL??CATS.opol??{};
const category=str(OPUROCAT.PRINCIPAL??OPUROCAT.principal??SEO.CATEGORIA??SEO.category);
const categoryOpol=str(OPOLCAT.PRINCIPAL??OPOLCAT.principal??SEO.CATEGORIA??SEO.category);
const categoryOpolSecondary=str(OPOLCAT.SECUNDARIA??OPOLCAT.secundaria)||null;
const tags = arr(SEO.ETIQUETAS ?? SEO.tags);

// v1.2.12 — PREFLIGHT DE CONTRATO v1.2.
// OPURO valida existencia después contra WordPress por coincidencia exacta de nombre.
// OPOL conserva el snapshot v1.1 para catálogo y jerarquía padre-hija.
const CATEGORY_CATALOG = {
  schema: "OPMX_CATEGORY_CATALOG",
  schema_version: "1.1",
  generated_at: "2026-09-24T06:09:53.754Z",
  OPOL_ALLOWED: ["CIENCIA", "CONGRESO", "DIPUTADOS", "SENADORES", "CULTURA", "DEPORTES", "ECONOMÍA", "EDUCACIÓN", "ESTADOS", "BAJA CALIFORNIA", "GOBIERNO", "INTERNACIONAL", "JUSTICIA", "MEDIO AMBIENTE", "MEGALÓPOLIS", "OPINIÓN", "POLÍTICA", "TECNOLOGÍA", "TURISMO", "Uncategorized"],
  OPOL_CATEGORIES: [{"name": "CIENCIA", "parent_name": null, "parent_id": 0}, {"name": "CONGRESO", "parent_name": null, "parent_id": 0}, {"name": "DIPUTADOS", "parent_name": "CONGRESO", "parent_id": 4}, {"name": "SENADORES", "parent_name": "CONGRESO", "parent_id": 4}, {"name": "CULTURA", "parent_name": null, "parent_id": 0}, {"name": "DEPORTES", "parent_name": null, "parent_id": 0}, {"name": "ECONOMÍA", "parent_name": null, "parent_id": 0}, {"name": "EDUCACIÓN", "parent_name": null, "parent_id": 0}, {"name": "ESTADOS", "parent_name": null, "parent_id": 0}, {"name": "BAJA CALIFORNIA", "parent_name": "ESTADOS", "parent_id": 10}, {"name": "GOBIERNO", "parent_name": null, "parent_id": 0}, {"name": "INTERNACIONAL", "parent_name": null, "parent_id": 0}, {"name": "JUSTICIA", "parent_name": null, "parent_id": 0}, {"name": "MEDIO AMBIENTE", "parent_name": null, "parent_id": 0}, {"name": "MEGALÓPOLIS", "parent_name": null, "parent_id": 0}, {"name": "OPINIÓN", "parent_name": null, "parent_id": 0}, {"name": "POLÍTICA", "parent_name": null, "parent_id": 0}, {"name": "TECNOLOGÍA", "parent_name": null, "parent_id": 0}, {"name": "TURISMO", "parent_name": null, "parent_id": 0}, {"name": "Uncategorized", "parent_name": null, "parent_id": 0}]
};

const CONTROL = d.CONTROL_EDITORIAL ?? d.control_editorial ?? {};
const controlEstado = str(CONTROL.ESTADO ?? CONTROL.estado).toUpperCase();

if (controlEstado !== 'LISTO') {
  throw new Error(
    `CONTROL_EDITORIAL_NO_LISTO: el Publisher sólo admite paquetes con CONTROL_EDITORIAL.ESTADO = LISTO. Valor recibido: "${controlEstado || '(vacío)'}".`
  );
}

if (!category) {
  throw new Error('CATEGORIA_OPURO_NO_AUTORIZADA: falta CATEGORIAS.OPURO.PRINCIPAL.');
}
if (!categoryOpol) {
  throw new Error('CATEGORIA_OPOL_NO_AUTORIZADA: falta CATEGORIAS.OPOL.PRINCIPAL.');
}
if (!CATEGORY_CATALOG.OPOL_ALLOWED.includes(categoryOpol)) {
  throw new Error(
    `CATEGORIA_OPOL_NO_AUTORIZADA: "${categoryOpol}" no existe literalmente en sites.OPOL.allowed_names del catálogo OPMX v${CATEGORY_CATALOG.schema_version}. No se enviará nada a WordPress.`
  );
}

if (categoryOpolSecondary !== null) {
  const child = CATEGORY_CATALOG.OPOL_CATEGORIES.find(x => x.name === categoryOpolSecondary);
  if (!child || Number(child.parent_id) === 0 || child.parent_name !== categoryOpol) {
    throw new Error(
      `CATEGORIA_OPOL_JERARQUIA_INVALIDA: "${categoryOpolSecondary}" no es hija literal de "${categoryOpol}" en el catálogo OPMX v${CATEGORY_CATALOG.schema_version}. No se enviará nada a WordPress.`
    );
  }
}

const seoCategory = str(SEO.CATEGORIA ?? SEO.category);
if (seoCategory !== category) {
  throw new Error(
    `SEO_CATEGORIA_INCONSISTENTE: SEO.CATEGORIA debe ser idéntica a CATEGORIAS.OPURO.PRINCIPAL. Recibido SEO="${seoCategory}" y OPURO="${category}".`
  );
}

const htmlFinal = str(d.HTML_FINAL ?? d.html_final);
const gutenbergFinal = str(d.GUTENBERG_FINAL ?? d.GUTEMBERG_FINAL ?? d.gutenberg_final);
const gutenbergEnriquecidoFinal = str(d.GUTENBERG_ENRIQUECIDO_FINAL ?? d.gutenberg_enriquecido_final);

const heroOpuro = {
  url: str(HERO.URL ?? HERO.url),
  alt_text: str(HERO.ALT ?? HERO.alt_text),
  title: str(HERO.TITULO_IMAGEN ?? HERO.title),
  caption: str(HERO.LEYENDA ?? HERO.caption),
  description: str(HERO.DESCRIPCION ?? HERO.description),
  credit: HERO.CREDITO ?? HERO.credit ?? null,
  class_name: str(HERO.CLASE_HERO ?? HERO.class_name)
};
heroOpuro.slug = '';

const featuredOpuro = {
  url: str(FEATURED_OPURO.URL ?? FEATURED_OPURO.url),
  alt_text: str(FEATURED_OPURO.ALT ?? FEATURED_OPURO.alt_text)
};
featuredOpuro.slug = '';

const featuredOpol = {
  url: str(FEATURED_OPOL.URL ?? FEATURED_OPOL.url),
  alt_text: str(FEATURED_OPOL.ALT ?? FEATURED_OPOL.alt_text)
};
featuredOpol.slug = '';

// v1.1.6 — validación condicionada por destino.
// Los campos editoriales comunes siguen siendo obligatorios.
// Los artefactos y medios específicos sólo se exigen si ese destino será creado.

const commonRequired = {
  title,
  slug,
  excerpt,
  primaryKeyword,
  tags
};

if (execution.create_opuro) {
  commonRequired.category = category;
}
if (execution.create_opol) {
  commonRequired.categoryOpol = categoryOpol;
}

const commonMissing = Object.entries(commonRequired)
  .filter(([, v]) => Array.isArray(v) ? v.length === 0 : !v)
  .map(([k]) => k);

if (commonMissing.length) {
  throw new Error(`OPMX MASTER incompleto para ${execution.destination}. Faltan campos comunes/seleccionados: ${commonMissing.join(', ')}`);
}

if (execution.create_opuro) {
  const requiredOpuro = {
    gutenbergEnriquecidoFinal,
    heroOpuroUrl: heroOpuro.url,
    featuredOpuroUrl: featuredOpuro.url,
    featuredOpuroAlt: featuredOpuro.alt_text
  };

  const missingOpuro = Object.entries(requiredOpuro)
    .filter(([, v]) => !v)
    .map(([k]) => k);

  if (missingOpuro.length) {
    throw new Error(`OPMX MASTER incompleto para Oxígeno Puro. Faltan: ${missingOpuro.join(', ')}`);
  }

  if (!/<!--\s*wp:[a-z0-9/-]+/i.test(gutenbergEnriquecidoFinal)) {
    throw new Error('GUTENBERG_ENRIQUECIDO_FINAL es obligatorio para OPURO y debe contener bloques Gutenberg serializados.');
  }

  const forbiddenEnriched = [
    /opmx-editorial/i, /data-opmx/i, /<!--\s*wp:html/i,
    /<\/?(?:article|header|footer)\b/i, /<h1\b/i, /\{\{[^}]+\}\}/
  ];
  if (forbiddenEnriched.some(rx => rx.test(gutenbergEnriquecidoFinal))) {
    throw new Error('GUTENBERG_ENRIQUECIDO_FINAL contiene un marcador, wrapper o placeholder no permitido.');
  }

  const allowedBlocks = new Set(['paragraph', 'heading', 'list', 'quote', 'image']);
  const blockNames = [...gutenbergEnriquecidoFinal.matchAll(/<!--\s*\/?wp:([a-z0-9/-]+)/gi)].map(match => match[1].replace(/^core\//, ''));
  if (!blockNames.length || blockNames.some(name => !allowedBlocks.has(name))) {
    throw new Error(`GUTENBERG_ENRIQUECIDO_FINAL usa bloques no autorizados: ${[...new Set(blockNames.filter(name => !allowedBlocks.has(name)))].join(', ') || '(sin bloques)'}.`);
  }
  if (/<!--\s*wp:image/i.test(gutenbergEnriquecidoFinal)) {
    if (!/\bwp-image-\d+\b/i.test(gutenbergEnriquecidoFinal) || !/\balt=(['"]).*?\1/i.test(gutenbergEnriquecidoFinal)) {
      throw new Error('Todo core/image enriquecido debe usar un adjunto nativo wp-image-{id} y conservar ALT literal.');
    }
  }

  if (heroOpuro.url !== '{{OPMX:HERO_OPURO}}') {
    throw new Error(`HERO_OPURO.URL debe ser exactamente {{OPMX:HERO_OPURO}}. Valor recibido: ${heroOpuro.url}`);
  }
  if (featuredOpuro.url !== '{{OPMX:DESTACADA_OPURO}}') {
    throw new Error(`DESTACADA_OPURO.URL debe ser exactamente {{OPMX:DESTACADA_OPURO}}. Valor recibido: ${featuredOpuro.url}`);
  }
  if (!binary.hero_file) throw new Error('Falta el archivo HERO (hero_file) para OPURO.');
  if (!binary.featured_file) throw new Error('Falta el archivo DESTACADA (featured_file) para OPURO.');
}

if (execution.create_opol) {
  const requiredOpol = {
    gutenbergFinal,
    featuredOpolUrl: featuredOpol.url,
    featuredOpolAlt: featuredOpol.alt_text
  };

  const missingOpol = Object.entries(requiredOpol)
    .filter(([, v]) => !v)
    .map(([k]) => k);

  if (missingOpol.length) {
    throw new Error(`OPMX MASTER incompleto para OXígeno Político. Faltan: ${missingOpol.join(', ')}`);
  }

  if (!/<!--\s*wp:[a-z0-9/-]+/i.test(gutenbergFinal)) {
    throw new Error('GUTENBERG_FINAL es obligatorio para OPOL y debe contener bloques Gutenberg reales.');
  }

  if (featuredOpol.url !== '{{OPMX:DESTACADA_OPOL}}') {
    throw new Error(`DESTACADA_OPOL.URL debe ser exactamente {{OPMX:DESTACADA_OPOL}}. Valor recibido: ${featuredOpol.url}`);
  }
  if (!binary.featured_file) throw new Error('Falta el archivo DESTACADA (featured_file) para OPOL.');
}

return {
  json: {
    execution,
    canonical: {
      title,
      subtitle,
      slug,
      excerpt,
      meta_description: metaDescription,
      primary_keyword: primaryKeyword,
      secondary_keywords: secondaryKeywords,
      keywords_all: keywordsAll || [primaryKeyword, ...secondaryKeywords].filter(Boolean).join(', '),
      keywords_list: keywordsList.length ? keywordsList : [primaryKeyword, ...secondaryKeywords].filter(Boolean),
      keywords: keywordsList.length ? keywordsList : [primaryKeyword, ...secondaryKeywords].filter(Boolean),
      category,
      categories:{opuro:{principal:category},opol:{principal:categoryOpol,secundaria:categoryOpolSecondary}},
      tags,
      html_final: htmlFinal,
      gutenberg_final: gutenbergFinal,
      gutenberg_enriquecido_final: gutenbergEnriquecidoFinal,
      images: {
        hero_opuro: heroOpuro,
        featured_opuro: featuredOpuro,
        featured_opol: featuredOpol
      },
      status: 'READY_FOR_SELECTED_DRAFTS',
      author: {
        id: authorId,
        source: authorSource
      }
    },
    original: d
  },
  binary
};
